import{b as e,O as t,g as a,j as l}from"./chunks/framework.DcaUmd3X.js";const i=JSON.parse('{"title":"终身成长（全新修订版）","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/growth-mindset/index.md","filePath":"读书感悟/电子书架/38.终身成长.md","lastUpdated":1781614933000}'),p={name:"reading/digital/growth-mindset/index.md"};function c(u,o,r,b,q,k){return t(),a("div",null,[...o[0]||(o[0]=[l('<h1 id="终身成长-全新修订版" tabindex="-1">终身成长（全新修订版） <a class="header-anchor" href="#终身成长-全新修订版" aria-label="Permalink to &quot;终身成长（全新修订版）&quot;">​</a></h1><p><code>卡罗尔·德韦克</code> <code>励志成长</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 你的基本能力是可以通过你的努力来培养的。</p></blockquote><blockquote><p>📌 人们在先天的才能和资质、兴趣或者性情方面有着各种各样的不同，每个人都可以通过努力和个人经历来改变和成长。</p></blockquote><blockquote><p>📌 桑普拉斯说：“当你坐在场边换边休息的时候，想一想之前的几局比赛，已经输了第一局……回到场上拿下接下来的三局。还有时间。你要反思一下之前比赛中的问题，然后战胜这些问题。”</p></blockquote><blockquote><p>📌 著名的婚姻专家艾伦·贝克（Aaron Beck）说过，对两性关系来说，最具毁灭性的想法之一就是：“如果我们需要努力，这说明我们的关系里存在非常严重的问题。”</p></blockquote><blockquote><p>📌 希拉里很难去原谅一个她认为是骗子的人。她只愿意去原谅一个她认为可以认真对待自己的问题并尝试着去成长的人。</p></blockquote><blockquote><p>📌 “表扬孩子时，不应该表扬他们的个性特质，而应该表扬他们的努力和成就。”</p></blockquote><blockquote><p>📌 泰格回应说：“我的父母给我的人生带来了最重要的影响。他们告诉我要去付出，付出我的时间、才能，最重要的是我的爱。”</p></blockquote><blockquote><p>📌 “一个成功学生的主要目标是拓展自己的知识，拓展自己思考和探索世界的方法。他们不会将分数当作自己的最终结果，而是将它看作帮助自己继续成长的一个途径。”</p></blockquote><blockquote><p>📌 是我们希望他们能够领会的努力过程：努力工作，尝试新策略，听取意见。</p></blockquote><blockquote><p>📌 对我来说，今天有哪些学习和成长的机会？对我周围的人呢？ 在思考如何利用这些机会的时候，制定一个计划，然后问自己： 我将在何时、何地、用什么方式开始实行这个计划？ 思考何时何地和用什么方式才能让你的计划更加具体。思考用什么方式能让你行动起来，去寻找一切方法，将你的计划付诸实践并获得成功。 当你遇到不可避免的阻碍与挫折时，制定一个新的计划，并再问一遍自己： 我将在何时、何地、用什么方式开始实行我的新计划？ 不管你感觉多差，都要去这样做！ 获得成功后，别忘了问自己： 要保持不断成长，我还要做些什么？ 要记住，正如伟大的棒球手阿莱克斯·罗德里格兹所说：“你要么成功，要么失败。”你也可以像他一样，成为决定自己未来方向的人。</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 只有正确认识到自己的不足，才能想办法弥补所缺的东西</p><p>📌 杰出的个人有着“一种能够准确评估自己的能力和不足的独特才能”</p></blockquote><blockquote><p>💭 纠结对与错而不是注重学到了多少，在短时间内可能不会感觉到什么，但是长久的发展会让你与他人的距离越来越远</p><p>📌 固定型思维模式者只会对反映其能力高低的反馈展现出兴趣。他们的脑波显示，他们在被告知自己的答案是对是错的时候注意力非常集中，但他们在得到可以帮助他们学习的信息时没有展现出一丝兴趣。即使他们自己的答案错了，对正确答案也毫不关心。</p></blockquote><blockquote><p>💭 多思考，不要一味的追求结果，尽可能的将所看到的东西转换成为自己的</p><p>📌 我会寻找串联每个讲座的主题以及潜在规律”，还有“我不断重新审视自己的错误，直到我弄明白错在哪里</p></blockquote><blockquote><p>💭 一次失败不算什么，争取下一次成功，不行就下下次，坚持下去，就算结果不如人意那也是一种成长</p><p>📌 但是后来她恍然大悟，突然间明白了什么样的人才是冠军：在需要的时候可以提高自己水平的人。当比赛处于危急时刻，他们能够突然拿出“此前三倍的韧劲去扳回比分”。</p></blockquote><blockquote><p>💭 唯有热爱，可抵岁月漫长</p><p>📌 米娅·哈姆告诉我们：“每次比赛或者练习之后，如果你走下运动场时认为你自己尽了全力，那么你永远是一个胜利者。”为什么美国人热爱她所在的球队？“他们看到我们是真正热爱这项运动的，我们对彼此、对每场比赛都付出了全部的努力。”</p></blockquote><blockquote><p>💭 每一次经历都是一种成长的过程</p><p>📌 以前认为爱可以战胜一切，但是现在我知道，爱是需要很多其他支持才能存活下去的。”这个人接着说：“我也知道了什么样的人才是适合我的。我认为，每一段关系都会让你越来越了解自己，你会渐渐看到适合自己的人到底是什么样的。”</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>人们在先天的才能和资质、兴趣或者性情方面有着各种各样的不同，每个人都可以通过努力和个人经历来改变和成长。</p></blockquote>',22)])])}const n=e(p,[["render",c]]);export{i as __pageData,n as default};
